import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const d=JSON.parse('{"title":"01 · 房价与土地财政的底层逻辑（知识手册）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/tianya/handbook/01_房价与土地财政的底层逻辑.md","filePath":"topics/tianya/handbook/01_房价与土地财政的底层逻辑.md"}'),g={name:"topics/tianya/handbook/01_房价与土地财政的底层逻辑.md"};function u(q,t,a,l,i,p){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="_01-·-房价与土地财政的底层逻辑-知识手册" tabindex="-1">01 · 房价与土地财政的底层逻辑（知识手册） <a class="header-anchor" href="#_01-·-房价与土地财政的底层逻辑-知识手册" aria-label="Permalink to &quot;01 · 房价与土地财政的底层逻辑（知识手册）&quot;">​</a></h1><blockquote><p>知识来源与标记：【K1/K2/K3】=kkndme《KK三部曲》（2010-2011）；【C】=《一个炒房人的终极预测——调控将彻底失败》（2010.4-10）；【B】=《北望帝都》（2010.11）；【F】=《全面阐述降低房价的四项基本原则》（2005.11）。本文不转述观点，直接以知识陈述呈现；每节末附<strong>适用条件与失效条件</strong>——失效本身也是知识。</p></blockquote><hr><h2 id="模块一-利益分析法——怎么拆解一个政策" tabindex="-1">模块一：利益分析法——怎么拆解一个政策 <a class="header-anchor" href="#模块一-利益分析法——怎么拆解一个政策" aria-label="Permalink to &quot;模块一：利益分析法——怎么拆解一个政策&quot;">​</a></h2><p><strong>核心公理</strong>：辨别利益是看透一切事物真相的武器【K1】。任何政策都是利益分配方案，读政策就是回答三个问题：<strong>谁受益、谁承担风险、谁买单</strong>。</p><p><strong>操作步骤</strong></p><ol><li>列出全部利益主体：中央、地方政府、银行、开发商、炒房客、有房者、无房刚需。</li><li>给每个主体标注：受益方式、风险承担方式、话语权大小。<strong>话语权与受益度不对称的一方，通常是买单者</strong>。</li><li>听&quot;喊得最响的人&quot;：媒体声量最大的往往是风险转出方。例：开发商渲染&quot;空置率高会拖垮银行&quot;，真实含义是要挟全民接受高房价来救开发商【F】。</li></ol><p><strong>推演实例一：2010年调控的真实靶子</strong>【K1】</p><ul><li>受益清点：地方政府（卖地净赚、无风险）、开发商、炒房客全部受益，唯独中央不受益，还独家承担金融风险。</li><li>风险链条：土地完全垄断→地方政府是无风险买卖；商品房二级市场自由竞争→风险积聚在银行；银行是国家的→风险最终由中央扛；央企出钱最多、风险最大，却只分残羹。&quot;银行与央企是左兜和右兜，银行与民营开发商是官与民。&quot;</li><li>结论：调控目的不是降价，而是①提高资金门槛踢出小开发商小炒客；②让国家队从一级市场（规划、拆迁、开发）一条龙进场；③把风险主体从&quot;民&quot;换成&quot;自己人&quot;。证据：调控板子只打二套房与投资客，从不碰土地垄断本身。</li></ul><p><strong>推演实例二：压房价的代价是通胀</strong>【K1】 印钞是常态→超发货币必须有去处→调控压住楼市成交量→资金流向可储存的民生品（2010年的大蒜、绿豆、姜）→物价上涨→人工成本上涨→建筑成本上涨→反推房价。而农产品涨价对政权的威胁远大于房价（历史改朝换代皆由大饥荒引发），所以调控必然雷声大雨点小——这不是阴谋，是目标函数排序。</p><p><strong>失效条件</strong>：利益分析法默认中央与地方目标一致且厌恶风险。当中央主动选择收缩（2021年三道红线），地方与开发商同时变成受损方时，&quot;政府不会让房价跌&quot;的推论失效——方法仍有效，但前提必须重估。</p><hr><h2 id="模块二-房地产三级垄断模型" tabindex="-1">模块二：房地产三级垄断模型 <a class="header-anchor" href="#模块二-房地产三级垄断模型" aria-label="Permalink to &quot;模块二：房地产三级垄断模型&quot;">​</a></h2><p><strong>第一级：土地垄断</strong>【K1】【F】。地方政府垄断收购权（低价征地拆迁）与出售权（招拍挂、价高者得）。关键数字：1999年全国招拍挂出让金114亿元（约1057元/㎡）；2003年前9个月已达1376亿，比1999年全年增11倍【F】；2004年&quot;831大限&quot;禁止低价协议出让后，地价与房价同步飙升。土地出让金=<strong>第二财政</strong>，垄断市场必产生超额利润（参照电信、石油），高房价就是垄断利润的体现。</p><p><strong>第二级：开发垄断</strong>【K1】。一级市场（城市规划、城中村改造、旧房拆迁、综合体开发）门槛极高，只有国家队玩得起。其独特能力是<strong>创造需求</strong>：&quot;你不是有房子吗？我拆掉你的房子，看你有没有刚需。&quot;拆迁的本质不是改善民生，是生产刚需。</p><p><strong>第三级：房租垄断</strong>【K1】。公租房三重功能：①少量房源做样子（如同重点小学留几个名额给外来务工子女，能不能上另说）；②优先安置体制内底层员工；③对体制外&quot;稳定收钱&quot;。推高市场租金的两只手：减少可出租房源（北京拆迁廉价城中村）、抬高竞争房源成本（公租房免房产税、私房要交）→公租房&quot;打个9折安抚底层，黑锅由竞争房源的房东背&quot;。</p><p><strong>双轨制：保障房的真实流向</strong>【K1】【K3】。经适房指标大量被体制内福利房占用：昆明某盘市场价12000元/㎡，体制内团购仅3000-5000，统计均价被拉到5000多，账面成了&quot;低房价城市&quot;，普通人实际成交7000-10000；广州某铁路福利房市价9.1万/㎡、福利价8千，一转手千万利润。宣传逻辑：1000套廉租房里990套给公务员，10套拿出来抽号，抽中者感激涕零——&quot;中国的很多事情只能宣传，不可能推广&quot;。另有城市拆迁发6000元/㎡购房券、限一年使用，结果是拆迁户拿券抢买8000元的房，当地均价从5000冲到10000。</p><p><strong>管仲模型：限购=官方承认商品房是奢侈品</strong>【K3】。管仲让齐桓公带头穿&quot;绨&quot;抬价、限制产量——奢侈品一旦量产就不再是奢侈品。政府明白商品房同理，所以限购+抑制开发：<strong>稀缺才尊贵</strong>。推论：指望限购降房价是方向性错误，限购是价格同盟的官方盖章。</p><p><strong>失效条件</strong>：本模型隐含燃料是货币持续超发+土地财政正循环。2021年后循环断裂（见模块八），垄断依旧、价格照跌——垄断真正保住的是<strong>分配权</strong>，不是价格下限。</p><hr><h2 id="模块三-调控-政策-媒体五阶段剧本" tabindex="-1">模块三：调控&quot;政策-媒体五阶段剧本&quot; <a class="header-anchor" href="#模块三-调控-政策-媒体五阶段剧本" aria-label="Permalink to &quot;模块三：调控&quot;政策-媒体五阶段剧本&quot;&quot;">​</a></h2><p>【C】给出的完整剧本，至今仍是解读政策周期的模板：</p><ol><li><strong>前期</strong>：媒体集中揭露一线城市暴涨、渲染民生痛苦——制造舆论势能。</li><li><strong>出台</strong>：痛表决心，&quot;史上最严&quot;。</li><li><strong>中期</strong>：夸大成果——拿个别炒家抛售、个别楼盘降价的孤例当全局证据（当年&quot;深圳某人抛售100套&quot;后被证伪）。</li><li><strong>后期</strong>：开发商集体&quot;做秀式&quot;降价，幅度远小于此前涨幅，做给两方看：给百姓看（吸引人气）、给政府看（要挟救市）；媒体同步渲染资金链紧张、上下游惨淡。</li><li><strong>终局</strong>：政府托市，由明转暗。</li></ol><p><strong>托市四步</strong>（同帖后续推演）：①媒体把&quot;下跌预期&quot;改写为&quot;企稳预期&quot;，鼓动刚需&quot;现在是最好的时机&quot;+宣传租金上涨；②不允许出现实质性下跌；③明政策不变、暗信贷放松——大额消费贷、抵押经营贷，名义全款实为借钱；④仍跌则分步放松限贷限购；若暴涨则行政压银行+媒体再吹风。</p><p><strong>散户应对</strong>：阶段1-2不接飞刀也不追涨；阶段3-4恰是选房窗口（房源回流、议价空间出现），出手信号有三个：新盘价低于周边二手、看房人回升、多宗土地流拍【K1】；阶段5执行既定计划而非追高。二三线城市与一线城市节奏不同，不能照搬【C】。</p><p><strong>案例校验</strong>：08年调控→09年救市→10年暴涨，剧本完整走通一轮；恒大&quot;宣布降价&quot;实为营销【C】；2010年燕郊从1万跌至6-7千，被解读为&quot;敲山震虎&quot;的最小代价示范——事后看，燕郊2017年腰斩才是真实的风险定价。</p><p><strong>失效条件</strong>：剧本默认&quot;政府最终必救市&quot;。2021-2025年阶段4之后换成了新剧本：救项目不救房价（保交楼、白名单、收储）——<strong>托量不托价</strong>。读剧本先辨认这一轮救的是成交量还是价格。</p><hr><h2 id="模块四-房价决定模型" tabindex="-1">模块四：房价决定模型 <a class="header-anchor" href="#模块四-房价决定模型" aria-label="Permalink to &quot;模块四：房价决定模型&quot;">​</a></h2><p><strong>1. 精英收入论 vs 平均收入论</strong>【K1】。房价由<strong>买得起的那部分人的边际出价</strong>决定，不由平均收入决定。金字塔结构下顶端10%就是一亿多人，超过多数西方国家总人口；北上广深+30个省会要承载这批人。推论：均价、房价收入比、空置率都无法解释核心区房价——&quot;月入两三千住不起四环&quot;与&quot;四环房子有没有买家&quot;是两个问题。</p><p><strong>2. 稀缺性是相对货币而言</strong>【K1】。砖头可无限复制，位置不能；但土地稀缺本身不直接生成涨价，&quot;人民币印多了、资金没去处，商品房才涨价&quot;。类比择校：重点中学名额稀缺→滋生加分项（送钱）→炒房客就是住房市场的加分项，与&quot;泡沫&quot;无关，是稀缺的必然衍生品。</p><p><strong>3. 租售比有两种修平方式</strong>【K1】。房价跌，或房租涨——政府选后者，因为房租比房产税更可操作。类比1990年前的和田玉长期低价，不可能持续。</p><p><strong>4. 通胀-蓄水池机制</strong>【K1】。房地产兼具投资品+必需品双重属性：让精英保值，同时吸走中下层未来数十年的结余。蓄水池一旦不蓄水，超发货币就漫向民生品——这是&quot;维稳优先于降价&quot;的经济学表述。</p><p><strong>5. 城市价值=辐射腹地的外部购买力</strong>【C】。本地收入解释不了三亚（本地无富人、房价却高），因为买家来自全国。广州追不上京沪的五条理由：辐射面小、周边城市化好（东莞惠州可替代）、深圳分流、高铁疏散、历史包袱。判断城市看<strong>外来人口流入潜力与高收入人口占比</strong>；算房价收入比必须把外地买家算进去（青岛的收入比要加上北京买家）。</p><p><strong>6. 分化时代三条</strong>【K3】：远郊在配套不跟进时长期滞涨且难出租；城中心、新政府所在地、地铁周边、政府重金新区持续涨；120-200㎡大中户型将贵过小户型。旅游地产三要素：资源、交通、配套，缺一不可——大理、弥勒达标（昆明2小时车程内），腾冲、版纳先天不足，2026年回看完全正确。</p><p><strong>7. 城市卡位论</strong>【B】：买房不是上升一层，是<strong>避免滑落一层</strong>；房子是留在牌桌上的资格。</p><p><strong>失效条件</strong>：精英收入论与蓄水池论依赖货币超发且信贷愿意流入楼市。2021年后货币仍宽松，但居民加杠杆的意愿与能力成为新约束——印钞不再必然变成房价（资金转向存款、国债与提前还贷）。现代版判断必须加一条：<strong>居民部门资产负债表状态</strong>。</p><hr><h2 id="模块五-炒房人的融资渠道——调控为何打不着真炒家" tabindex="-1">模块五：炒房人的融资渠道——调控为何打不着真炒家 <a class="header-anchor" href="#模块五-炒房人的融资渠道——调控为何打不着真炒家" aria-label="Permalink to &quot;模块五：炒房人的融资渠道——调控为何打不着真炒家&quot;">​</a></h2><p>【C】的自述渠道清单：</p><ol><li><strong>实业贷款</strong>：有公司就有银行授信，以经营名义贷款，资金流向自定。</li><li><strong>房产抵押</strong>：50余套房先出一半，剩余抵押再滚。</li><li><strong>民间借贷</strong>：圈子内信誉借贷，利率高但渠道畅通。</li><li><strong>认贷不认房漏洞</strong>：多数城市只查贷款记录，还清再贷仍享首套——案例：朋友买第四套房，首付40%、利率七折。</li><li><strong>限购资质可造</strong>：成立公司容易，社保与完税可以&quot;做&quot;出来，成本相对利润可忽略。</li><li><strong>大额消费信贷</strong>：抵押已有房产拿七折消费贷，名义全款实为杠杆。</li></ol><p><strong>机制</strong>：首付50%、限套数、查社保，每一条精确命中的都是&quot;只有工资和按揭&quot;的人。政策设计的真实目标不是消灭炒房，而是<strong>不让全民炒房</strong>——把游戏资格收回给有办法的人【C】。这与【K1】&quot;踢出小炒客、让国家队进场&quot;互为印证：同一现象，两种表述。</p><p><strong>失效条件</strong>：2021年起严查经营贷消费贷违规入楼、资金穿透监管上线，这条通道被补上。知识更新：融资套利空间随监管颗粒度收窄而收缩，但&quot;行政约束穿透不了有组织资金&quot;的原理不变，只是换了形态（代持、境外、共有产权）。</p><hr><h2 id="模块六-房产税的转嫁机制与难产原因" tabindex="-1">模块六：房产税的转嫁机制与难产原因 <a class="header-anchor" href="#模块六-房产税的转嫁机制与难产原因" aria-label="Permalink to &quot;模块六：房产税的转嫁机制与难产原因&quot;">​</a></h2><p><strong>为什么收了也不降房价</strong>【K1】【C】： ①税不增加一套供给； ②持多套房的主力是公务员与普通多房家庭，不是职业炒家——职业炒家收几套租金就够交几十套的税，结果只有转嫁给租客； ③全球无&quot;因房产税降价&quot;的先例（美韩皆征）； ④年税0.5-1%低于年增值预期时无人抛售，反而推高租金、优化&quot;租售比&quot;。 推论：房产税的真实功能是<strong>土地卖完后的替代财源</strong>，不是调控工具（当年引数据：我国行政公务开支占财政约44%，日本约2.4%）。</p><p><strong>难产的四大障碍</strong>：</p><ol><li><strong>执行暴力化</strong>：真下决心收，就要容忍基层&quot;踹门扰民&quot;、打砸频发——唐德宗间架税引发兵变、被迫废税【K3】。</li><li><strong>产权底数不清</strong>：公房、军产、央产、小产权未联网未确权，&quot;五年内理清就算快的&quot;【C】。</li><li><strong>评估定价难题</strong>：评估价实质是政府强制定价，既要防阴阳合同，又要平衡强势群体利益——评估标准出不来，一切以评估价为基础的政策都无法推行【K3】。</li><li><strong>公平悖论</strong>：不公平法则（福利房免税、只征普通百姓）加剧社会矛盾；公平法则（小产权、福利房、权贵囤房一律征）执行阻力不可逾越——两害相权，选择不作为【K1】。</li></ol><p><strong>事后校验</strong>：2011年上海、重庆试点（增量+高端）；立法一再推迟，2021年财政部明确&quot;不具备扩大试点条件&quot;，至2026年仍无全国性开征。&quot;难产&quot;是这组帖子命中度最高的预测。</p><hr><h2 id="模块七-北望帝都的点位方法与兑现清单" tabindex="-1">模块七：北望帝都的点位方法与兑现清单 <a class="header-anchor" href="#模块七-北望帝都的点位方法与兑现清单" aria-label="Permalink to &quot;模块七：北望帝都的点位方法与兑现清单&quot;">​</a></h2><p><strong>方法</strong>【B】：①<strong>国家战略资本开支定城市命运</strong>——预见中国以欧亚高铁+亚非高铁（后名&quot;一带一路&quot;，2013年正式提出）争大陆权，枢纽西安、成都、重庆受益；②四因子：中国崛起、人民币升值、城市化、通胀；③被忽略的购买力——下乡调研发现&quot;农民有钱的程度让人吃惊&quot;（有钱农民+拆村并居补偿款，例：西部某村拆迁补75万），拆村并居=把9亿农民逼向商品房市场的新圈地；④不要用自己的收入衡量房价。</p><p><strong>十年点位与兑现（2010→2020）</strong>：</p><table tabindex="0"><thead><tr><th>城市</th><th>预测</th><th>2026年回看</th></tr></thead><tbody><tr><td>北京四环内</td><td>8万</td><td><strong>兑现</strong>：2020-2021触线8-10万，随后回落</td></tr><tr><td>上海</td><td>7万</td><td><strong>大体兑现</strong>：内环早已超，全市均价约6-7万</td></tr><tr><td>深广</td><td>4-6万</td><td><strong>深圳严重低估</strong>：2021年破10万；广州接近</td></tr><tr><td>杭州</td><td>7万</td><td><strong>高估</strong>：实际3-4万</td></tr><tr><td>津汉宁成渝西</td><td>3-4万</td><td><strong>高估</strong>：实际1.5-2.5万，但方向对（中西部黄金期2016-2021）</td></tr></tbody></table><p><strong>可复用</strong>：基建资本开支→城市价值（后来的强省会战略验证方向）；卡位论。<strong>不可复用</strong>：&quot;十年之内任何时候买房都对&quot;——点位哲学只在单边上行期成立，2021年后同一句话变成最大亏损来源。知识化表述：<strong>点位判断与持有期回报是两回事，长周期预测不能用短周期择时兑现</strong>。</p><hr><h2 id="模块八-失效清单与失效机制——把教训写成知识" tabindex="-1">模块八：失效清单与失效机制——把教训写成知识 <a class="header-anchor" href="#模块八-失效清单与失效机制——把教训写成知识" aria-label="Permalink to &quot;模块八：失效清单与失效机制——把教训写成知识&quot;">​</a></h2><p><strong>失效判断清单（原判断→失效方式与机制）</strong>：</p><ol><li>&quot;土地垄断不改，房价就没有真正下跌的可能&quot;【K2】→2022-2026全国普跌两至四成。机制：垄断决定分配权，不决定价格下限；价格由土地财政循环是否运转决定。</li><li>&quot;调控必然失败&quot;【C】→短期对（2010-2021未压住），长期错：2016&quot;房住不炒&quot;后调控从周期工具变成方向约束，2021年三道红线、集中供地、贷款集中度管理四管齐下；2024-2026限购全面松绑仍无法止跌——不是调控失败了，是<strong>政策目标切换了</strong>。</li><li>&quot;一线永不崩&quot;【C】→京沪跌幅相对小但绝对跌，深圳、环京跌幅深。机制：没有城市能脱离居民资产负债表单独定价。</li><li>&quot;房租不可想象地涨&quot;【K3】→2022年后一线城市租金滞涨转跌。机制：租金锚定租客收入，收入预期下修直接压制房租。</li><li>&quot;通胀必反推房价&quot;【K1】→2024-2026货币宽松但房价仍跌。机制：货币传导从&quot;信贷→买房&quot;变成&quot;信贷→化债与存款&quot;，蓄水池自身漏水。</li><li>&quot;保租房=房租垄断&quot;【K1】→保租房大量面向体制外、租金低于市场，反而压制了私人房租。机制：房价不再上涨时，政府目标从&quot;收钱&quot;变为&quot;留住人&quot;。</li></ol><p><strong>共同失效机制（本手册最核心的知识）</strong>：上述模型的公理是<strong>土地财政正循环</strong>——卖地收入→基建与公共开支→推高地价预期→更多卖地。该循环的三个燃料：出口创汇带来的外汇占款（货币超发源头）、人口红利（增量需求）、居民部门加杠杆空间（资金来源）。出口引擎减速、2022年人口负增长、2021年居民杠杆见顶——三个燃料几乎同时耗尽，正循环反转为负循环（地卖不掉→财政收缩→配套放缓→预期下修→更卖不掉）。政府随之从&quot;做多方&quot;切换为&quot;化债方&quot;：救项目不救房价、收储存量房、默许以价换量。所有&quot;政府不会让房价跌&quot;的推论，失效点都在这里。</p><p><strong>公理检验法（可复用）</strong>：使用任何楼市模型前先问三问——①它的公理是否依赖特定财政/货币制度？②该制度的燃料（外汇、人口、居民杠杆）是否还在？③政府本阶段的目标函数是保价、保量还是化债？答案一变，结论全部重写。</p><p><strong>2026年仍然有效的部分</strong>：利益分析法（拆解收储、白名单、以旧换新照样好用）；五阶段剧本（救市同样走过表决心→夸大成果→真托底，只是托量不托价）；双轨制观察（配售型保障房重启，流向仍需用&quot;谁受益&quot;检验）；分化框架（核心地段、地铁、稀缺属性抗跌，2026年跌幅梯度完全吻合）；房产税难产判断。</p><p><strong>结语</strong>：这组帖子最值钱的不是结论，而是两种元能力——用利益结构而非道德叙事读政策，让你不被人骗；给每个模型写下失效条件，让你不骗自己。</p>',63)])])}const h=o(g,[["render",u]]);export{d as __pageData,h as default};
